#!/usr/bin/env python3
"""F09 — Nginx upstream file management (`xray balance`).

Preview evidence level: CONTAINER_VERIFIED (the real Go binary runs against a
real sandbox root and a real nginx `-t`; the fixed Bash baseline is executed
function-by-function from scripts/file_manager.sh; no data plane, no systemd,
no host writes, no network).

What the fixture proves:

* a Reality install generated by `xray generate --mode reality-balance
  --role primary` exposes exactly one loopback backend and passes `nginx -t`;
* `balance add` writes `server HOST:PORT weight=W max_fails=2 fail_timeout=10;`
  byte for byte the same file the Bash `fm_create_server_file` writes, runs a
  real `nginx -t`, and reports `changed=true` plus the two sandbox warnings;
* `balance list` sorts by host/port, prints TSV or `--json`, and never mutates
  the tree; `balance remove` deletes the fragment and rejects a second remove;
* duplicate hosts, reserved ports, invalid hosts, out-of-range ports/weights,
  loopback removal, wrong-port removal and unknown upstreams are refused with
  the measured exits, and a rejected write leaves no file behind;
* a broken nginx configuration makes `add` fail and removes the new fragment,
  and restoring the configuration makes the same add succeed;
* a TLS ws install accepts only ws/grpc/xhttp and writes `.wsServers`;
* a root without metadata exits 3, a root without the upstream anchor exits 1,
  and a root without the nginx binary exits 1 after removing the new file.

Approved differences (recorded in `baseline-compare.json`, not claimed as
parity): Bash lists only file names and has no JSON; Bash `rm` can delete the
loopback or the last backend; Bash overwrites duplicate hosts and never checks
reserved ports; Bash always reloads nginx while a sandbox root skips the reload.
"""
import hashlib
import json
import os
import re
import shutil
import socket
import ssl
import stat
import subprocess
import sys
import threading
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from fixture_support import run_fixture  # noqa: E402

LOOPBACK_RE = re.compile(r"^server 127\.0\.0\.1:(\d+) weight=(\d+) ", re.MULTILINE)
SERVER_RE = re.compile(r"^server ([^:]+):(\d+) weight=(\d+) max_fails=2 fail_timeout=10;$")
FRAGMENT_BODY = "server 10.0.0.2:8443 weight=60 max_fails=2 fail_timeout=10;\n"


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def sha256_file(path):
    return sha256_bytes(Path(path).read_bytes())


def extract_bash_function(text, name):
    match = re.search(rf"^{name}\(\) \{{\n.*?^\}}$", text, re.MULTILINE | re.DOTALL)
    return match.group(0) if match else None


def write_text(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    return path


def metadata(tls, transport):
    return {
        "schemaVersion": 1,
        "activeEngine": "xray",
        "role": "node",
        "tls": tls,
        "transport": transport,
        "runtimeConfigPath": "usr/local/etc/xray/config.json",
        "runtimeSha256": "b" * 64,
        "ownedResources": [],
        "updatedAt": "2026-01-01T00:00:00Z",
        "install": {"port": 9443, "serverNames": ["example.com"]},
        "balanceRole": "primary",
    }


def seed_root(root, tls, transport):
    root = Path(root)
    for sub in ("usr/local/nginx/sbin", "usr/local/nginx/conf", "usr/local/nginx/logs",
                "etc/idleleo/v1", "etc/idleleo/conf/nginx", "fragments"):
        (root / sub).mkdir(parents=True, exist_ok=True)
    os.symlink("/usr/sbin/nginx", root / "usr/local/nginx/sbin/nginx")
    write_text(root / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    write_text(root / "etc/idleleo/v1/metadata.json",
               json.dumps(metadata(tls, transport), indent=2) + "\n")
    return root


def rewrite_install_paths(text, root):
    root = str(root)
    return (text.replace("/etc/idleleo/conf/nginx", f"{root}/etc/idleleo/conf/nginx")
                .replace("/usr/local/nginx", f"{root}/usr/local/nginx"))


def bash_script(function, extension, queue, delete_loopback=False):
    stubs = f"""set -euo pipefail
OK=; GreenBG=; Font=; Green=; Error=; RedBG=; Warning=; YellowBG=; Red=
log_echo(){{ :; }}
gettext(){{ printf '%s' "$1"; }}
fm_display_width(){{ printf '%s' "${{#1}}"; }}
fm_restart_nginx_and_check_status(){{ :; }}
fm_list_files(){{ if [ "${{1:-}}" = true ]; then files=("127.0.0.1.${{fm_EXTENSION}}"); fi; }}
pkg_install(){{ :; }}
ID=ubuntu
QUEUE=({" ".join(queue)})
read_optimize(){{ local _p="$1" _v="$2" _d="${{3:-}}"; local _n="${{QUEUE[0]}}"; QUEUE=("${{QUEUE[@]:1}}"); [ -z "$_n" ] && _n="$_d"; printf -v "$_v" '%s' "$_n"; }}
fm_EXTENSION={extension}
{function}
"""
    verb = "fm_delete_file" if delete_loopback else 'printf "N\\n" | fm_create_server_file ""'
    return stubs + verb + "\n"


def run_bash(script, cwd, env):
    path = write_text(Path(cwd) / "baseline.sh", script)
    return subprocess.run(["bash", str(path)], cwd=str(cwd), env=env,
                          capture_output=True, text=True, timeout=60)


def main(f):
    f.need(f.bash_repo is not None,
           "F09 requires --bash-repo for the Bash file_manager baseline")
    file_manager = f.bash_repo / "scripts/file_manager.sh"
    f.need(file_manager.is_file(), f"Bash baseline not found: {file_manager}")
    f.need(shutil.which("nginx") is not None, "nginx must be installed in the container")
    f.need(Path("/usr/lib/nginx/modules/ngx_stream_module.so").is_file(),
           "nginx stream module is required for the Reality install")
    source = file_manager.read_text(encoding="utf-8")
    create_fn = extract_bash_function(source, "fm_create_server_file")
    delete_fn = extract_bash_function(source, "fm_delete_file")
    f.need(create_fn is not None, "fm_create_server_file not found in file_manager.sh")
    f.need(delete_fn is not None, "fm_delete_file not found in file_manager.sh")

    work = f.evidence / "f09-work"
    if work.exists():
        shutil.rmtree(work, ignore_errors=True)
    work.mkdir(parents=True, exist_ok=True)
    observed = {"baseline": {}, "reality": {}, "tls": {}}
    compare = {}

    # ---- S1: real Reality install and read-only list --------------------
    root = seed_root(work / "reality-root", "Reality", "raw")
    gen = f.run([f.go, "--root", root, "xray", "generate", "--mode", "reality-balance",
                 "--role", "primary", "--uuid", "eeeeeeee-4444-4444-8444-444444444444",
                 "--short-id", "abcd1234", "--server-names", "example.com",
                 "--out", root / "config.json", "--nginx-out", work / "reality-nginx.conf",
                 "--fragments-out", root / "fragments", "--json"])
    f.check(gen.rc == 0, "generate reality-balance rc=0", gen.text[:300])
    anchor = rewrite_install_paths((work / "reality-nginx.conf").read_text(encoding="utf-8"), root)
    write_text(root / "etc/idleleo/conf/nginx/00-xray.conf", anchor)
    for item in (root / "fragments").iterdir():
        shutil.copy2(item, root / "etc/idleleo/conf/nginx" / item.name)
    loopback_text = (root / "etc/idleleo/conf/nginx/127.0.0.1.realityServers").read_text()
    loopback_match = LOOPBACK_RE.match(loopback_text)
    f.check(loopback_match is not None and loopback_match.group(2) == "50",
            "generated loopback fragment has weight 50", loopback_text)
    loopback_port = int(loopback_match.group(1)) if loopback_match else 9443
    for log in ("tls_error.log", "sni_error.log"):
        (root / "usr/local/nginx/logs" / log).touch()
    write_text(root / "usr/local/nginx/conf/nginx.conf", f"""load_module /usr/lib/nginx/modules/ngx_stream_module.so;
pid {root}/usr/local/nginx/logs/nginx.pid;
error_log {root}/usr/local/nginx/logs/error.log;
events {{}}
include {root}/etc/idleleo/conf/nginx/00-xray.conf;
http {{}}
""")
    nginx = root / "usr/local/nginx/sbin/nginx"
    prefix = str(root / "usr/local/nginx") + "/"
    conf = root / "usr/local/nginx/conf/nginx.conf"
    t = f.run([nginx, "-t", "-p", prefix, "-c", conf])
    f.check(t.rc == 0, "real nginx -t accepts the generated Reality install", t.text[:300])

    conf_dir = root / "etc/idleleo/conf/nginx"
    tree_before = f.tree_digest(conf_dir)
    listing = f.run([f.go, "--root", root, "xray", "balance", "list", "--upstream", "reality"])
    f.check(listing.rc == 0, "reality balance list rc=0", listing.text[:200])
    lines = [line for line in listing.out.splitlines() if line.strip()]
    f.check(len(lines) == 1, "reality list has exactly the loopback backend", listing.out)
    if lines:
        fields = lines[0].split("\t")
        f.check(fields[:3] == ["127.0.0.1", str(loopback_port), "50"],
                "reality list TSV host/port/weight", lines[0])
        f.check(fields[3] == str(conf_dir / "127.0.0.1.realityServers"),
                "reality list TSV file", fields[3])
    listing_json = f.run([f.go, "--root", root, "xray", "balance", "list",
                          "--upstream", "reality", "--json"])
    payload = f.json_of(listing_json, "balance list --json") if listing_json.rc == 0 else None
    if payload:
        f.check(payload["upstream"] == "reality", "list json upstream", payload["upstream"])
        f.check(payload["changed"] is False and payload["probed"] is False,
                "list json changed/probed are false")
        f.check(payload["warnings"] == [], "list json has no warnings", str(payload["warnings"]))
        f.check(len(payload["backends"]) == 1 and payload["backends"][0]["host"] == "127.0.0.1"
                and payload["backends"][0]["port"] == loopback_port
                and payload["backends"][0]["weight"] == 50,
                "list json loopback entry", json.dumps(payload["backends"]))
    f.check(f.tree_digest(conf_dir) == tree_before, "list never mutates the config tree")
    observed["reality"]["root"] = str(root)
    observed["reality"]["loopbackPort"] = loopback_port
    observed["reality"]["nginxTest"] = t.rc

    # ---- S2: add writes the Bash-identical fragment ----------------------
    files_before = f.tree_digest(conf_dir)
    add = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                 "--host", "10.0.0.2", "--port", "8443", "--weight", "60", "--json"])
    added = f.json_of(add, "balance add --json") if add.rc == 0 else None
    f.check(add.rc == 0, "balance add rc=0", add.text[:300])
    fragment = conf_dir / "10.0.0.2.realityServers"
    go_bytes = fragment.read_bytes() if fragment.is_file() else b""
    f.check(go_bytes == FRAGMENT_BODY.encode(), "go fragment bytes", go_bytes.decode(errors="replace"))
    f.check(stat.S_IMODE(fragment.stat().st_mode) == 0o644, "fragment mode is 0644",
            oct(stat.S_IMODE(fragment.stat().st_mode)))
    if added:
        f.check(added["changed"] is True, "add json changed=true")
        f.check(added["file"] == str(fragment), "add json file", added["file"])
        f.check(added["probed"] is False, "add json probed=false")
        f.check([b["host"] for b in added["backends"]] == ["10.0.0.2", "127.0.0.1"],
                "add json backends sorted", str([b["host"] for b in added["backends"]]))
        f.check(any("no liveness probe" in w for w in added["warnings"]),
                "add warns about the skipped probe", str(added["warnings"]))
        f.check(any("reload skipped" in w for w in added["warnings"]),
                "add warns about the skipped reload", str(added["warnings"]))
    after_add = f.tree_digest(conf_dir)
    f.check(after_add != files_before, "add mutates the config tree")
    observed["reality"]["addFileSha256"] = sha256_bytes(go_bytes)
    observed["reality"]["addBytes"] = len(go_bytes)
    observed["reality"]["warnings"] = added["warnings"] if added else []

    # ---- S2b: --probe reaches a listening backend ----------------------
    addresses = subprocess.run(["hostname", "-I"], capture_output=True, text=True,
                               timeout=10).stdout.split()
    probe_host = next((ip for ip in addresses if not ip.startswith("127.")), "")
    f.need(probe_host != "", "a non-loopback container address is required for --probe")
    cert = work / "probe-cert.pem"
    key = work / "probe-key.pem"
    openssl = subprocess.run(["openssl", "req", "-x509", "-newkey", "rsa:2048", "-nodes",
                              "-subj", "/CN=example.com", "-days", "1",
                              "-keyout", str(key), "-out", str(cert)],
                             capture_output=True, text=True, timeout=60)
    f.need(openssl.returncode == 0, f"openssl cert generation failed: {openssl.stderr[:200]}")
    tls_ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    tls_ctx.load_cert_chain(str(cert), str(key))
    listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    listener.bind((probe_host, 0))
    listener.listen(5)
    probe_port = listener.getsockname()[1]

    def serve_probe():
        while True:
            try:
                conn, _ = listener.accept()
            except OSError:
                return
            try:
                with tls_ctx.wrap_socket(conn, server_side=True) as secure:
                    secure.recv(1)
            except (OSError, ssl.SSLError):
                pass

    threading.Thread(target=serve_probe, daemon=True).start()
    probe = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                   "--host", probe_host, "--port", str(probe_port), "--probe", "--json"])
    probe_json = f.json_of(probe, "probe add --json") if probe.rc == 0 else None
    listener.close()
    cert.unlink(missing_ok=True)
    key.unlink(missing_ok=True)
    f.check(probe.rc == 0, "probe add rc=0", probe.text[:220])
    if probe_json:
        f.check(probe_json["probed"] is True, "probe add reports probed=true")
        f.check(not any("no liveness probe" in w for w in probe_json["warnings"]),
                "probe add omits the no-probe warning", str(probe_json["warnings"]))
    probe_rm = f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream",
                      "reality", "--host", probe_host])
    f.check(probe_rm.rc == 0, "probe backend cleaned up", probe_rm.text[:160])

    # ---- S3: duplicate add is refused and changes nothing ----------------
    dup = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                 "--host", "10.0.0.2", "--port", "8443", "--weight", "60"])
    f.check(dup.rc == 1 and "already exists" in dup.text, "duplicate host rc=1", dup.text[:200])
    f.check(f.tree_digest(conf_dir) == after_add, "duplicate add leaves the tree unchanged")

    # ---- S4: remove deletes only that backend ---------------------------
    removed = f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream", "reality",
                     "--host", "10.0.0.2", "--port", "8443", "--json"])
    remove_json = f.json_of(removed, "balance remove --json") if removed.rc == 0 else None
    f.check(removed.rc == 0 and not fragment.exists(),
            "remove deletes the fragment", removed.text[:200])
    if remove_json:
        f.check(remove_json["changed"] is True and remove_json["file"] == str(fragment),
                "remove json changed/file")
        f.check([b["host"] for b in remove_json["backends"]] == ["127.0.0.1"],
                "remove json keeps only loopback")
    again = f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream", "reality",
                   "--host", "10.0.0.2", "--port", "8443"])
    f.check(again.rc == 1 and "no backend file" in again.text,
            "second remove rc=1", again.text[:200])

    # ---- S5: guard rails stay side-effect free --------------------------
    guard_before = f.tree_digest(conf_dir)
    guards = [
        ("remove loopback", ["remove", "--upstream", "reality", "--host", "127.0.0.1"], 1,
         "refusing to remove the local 127.0.0.1 backend"),
        ("reserved port", ["add", "--upstream", "reality", "--host", "10.0.0.3",
                           "--port", "443"], 1, "port 443 is reserved by the managed install"),
        ("invalid host", ["add", "--upstream", "reality", "--host", "bad host",
                          "--port", "8443"], 1, "invalid backend host"),
        ("port zero", ["add", "--upstream", "reality", "--host", "10.0.0.3",
                       "--port", "0"], 1, "backend port must be between 1 and 65535"),
        ("port too high", ["add", "--upstream", "reality", "--host", "10.0.0.3",
                           "--port", "65536"], 1, "backend port must be between 1 and 65535"),
        ("weight too high", ["add", "--upstream", "reality", "--host", "10.0.0.3",
                             "--port", "8443", "--weight", "101"], 1,
         "backend weight must be between 0 and 100"),
        ("weight negative", ["add", "--upstream", "reality", "--host", "10.0.0.3",
                             "--port", "8443", "--weight", "-1"], 1,
         "backend weight must be between 0 and 100"),
        ("unknown upstream", ["list", "--upstream", "nope"], 1,
         'upstream "nope" is not available on a Reality install'),
    ]
    for name, argv, want_rc, needle in guards:
        r = f.run([f.go, "--root", root, "xray", "balance", *argv])
        f.check(r.rc == want_rc and needle in r.text, f"{name} rc={want_rc}", r.text[:220])
    bad_port = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                      "--host", "10.0.0.3", "--port", "abc"])
    f.check(bad_port.rc == 2, "non-integer port exits 2", bad_port.text[:120])
    no_upstream = f.run([f.go, "--root", root, "xray", "balance", "add",
                         "--host", "10.0.0.9", "--port", "8443"])
    f.check(no_upstream.rc == 2, "missing --upstream exits 2", no_upstream.text[:120])
    unknown_flag = f.run([f.go, "--root", root, "xray", "balance", "list",
                          "--upstream", "reality", "--bogus"])
    f.check(unknown_flag.rc == 2, "unknown balance flag exits 2", unknown_flag.text[:120])
    f.check(f.tree_digest(conf_dir) == guard_before,
            "all rejected commands leave the config tree unchanged")

    # wrong port and missing file
    add9 = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                  "--host", "10.0.0.9", "--port", "8443"])
    f.check(add9.rc == 0, "prepare 10.0.0.9 backend", add9.text[:160])
    wrong_port = f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream",
                        "reality", "--host", "10.0.0.9", "--port", "9999"])
    f.check(wrong_port.rc == 1 and "no server on port 9999" in wrong_port.text,
            "wrong-port remove rc=1", wrong_port.text[:220])
    f.check((conf_dir / "10.0.0.9.realityServers").is_file(),
            "wrong-port remove keeps the file")
    missing = f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream",
                     "reality", "--host", "10.0.0.8", "--port", "8443"])
    f.check(missing.rc == 1 and "no backend file" in missing.text,
            "missing-file remove rc=1", missing.text[:220])
    cleanup = f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream",
                     "reality", "--host", "10.0.0.9"])
    f.check(cleanup.rc == 0, "cleanup 10.0.0.9 backend", cleanup.text[:160])

    # ---- S6: nginx -t failure rolls the fragment back ------------------
    main_conf = root / "usr/local/nginx/conf/nginx.conf"
    good_conf = main_conf.read_text(encoding="utf-8")
    write_text(main_conf, good_conf + "bogus_directive on;\n")
    broken = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                    "--host", "10.0.0.7", "--port", "8443"])
    bad_fragment = conf_dir / "10.0.0.7.realityServers"
    f.check(broken.rc == 1 and "nginx -t rejected" in broken.text,
            "broken nginx makes add fail", broken.text[:260])
    f.check(not bad_fragment.exists(), "failed nginx -t removes the new fragment")
    write_text(main_conf, good_conf)
    retry = f.run([f.go, "--root", root, "xray", "balance", "add", "--upstream", "reality",
                   "--host", "10.0.0.7", "--port", "8443"])
    f.check(retry.rc == 0 and bad_fragment.is_file(),
            "restored nginx lets the same add succeed", retry.text[:160])
    f.run([f.go, "--root", root, "xray", "balance", "remove", "--upstream", "reality",
           "--host", "10.0.0.7"])

    # ---- S7: TLS ws install --------------------------------------------
    tls_root = seed_root(work / "tls-root", "TLS", "ws")
    tgen = f.run([f.go, "--root", tls_root, "xray", "generate", "--mode", "tls",
                  "--transport", "ws", "--domain", "example.com", "--port", "443",
                  "--uuid", "eeeeeeee-4444-4444-8444-444444444444",
                  "--out", tls_root / "config.json", "--nginx-out", work / "tls-server.conf",
                  "--fragments-out", tls_root / "fragments", "--json"])
    f.check(tgen.rc == 0, "generate TLS ws rc=0", tgen.text[:240])
    tls_conf_dir = tls_root / "etc/idleleo/conf/nginx"
    for item in (tls_root / "fragments").iterdir():
        target = tls_conf_dir / item.name
        text = item.read_text(encoding="utf-8")
        target.write_text(rewrite_install_paths(text, tls_root), encoding="utf-8")
    write_text(tls_conf_dir / "03-xray-https.conf",
               "server { listen 9443; location / { proxy_pass http://xray-ws-server; } }\n")
    write_text(tls_root / "usr/local/nginx/conf/nginx.conf", f"""load_module /usr/lib/nginx/modules/ngx_stream_module.so;
pid {tls_root}/usr/local/nginx/logs/nginx.pid;
error_log {tls_root}/usr/local/nginx/logs/error.log;
events {{}}
http {{
    include {tls_conf_dir}/02-xray-server.conf;
    include {tls_conf_dir}/03-xray-https.conf;
}}
""")
    tls_test = f.run([tls_root / "usr/local/nginx/sbin/nginx", "-t", "-p",
                      str(tls_root / "usr/local/nginx") + "/",
                      "-c", tls_root / "usr/local/nginx/conf/nginx.conf"])
    f.check(tls_test.rc == 0, "real nginx -t accepts the TLS ws install", tls_test.text[:300])
    tls_reality = f.run([f.go, "--root", tls_root, "xray", "balance", "add", "--upstream",
                         "reality", "--host", "10.0.0.6", "--port", "8443"])
    f.check(tls_reality.rc == 1 and 'upstream "reality" is not available on a TLS install'
            in tls_reality.text, "TLS install refuses the reality upstream", tls_reality.text[:220])
    tls_add = f.run([f.go, "--root", tls_root, "xray", "balance", "add", "--upstream", "ws",
                     "--host", "10.0.0.5", "--port", "8443", "--weight", "60", "--json"])
    tls_json = f.json_of(tls_add, "tls add --json") if tls_add.rc == 0 else None
    ws_fragment = tls_conf_dir / "10.0.0.5.wsServers"
    ws_body = "server 10.0.0.5:8443 weight=60 max_fails=2 fail_timeout=10;\n"
    f.check(tls_add.rc == 0 and ws_fragment.read_text() == ws_body,
            "TLS ws add writes .wsServers", tls_add.text[:240])
    if tls_json:
        f.check(tls_json["upstream"] == "ws" and tls_json["changed"] is True,
                "TLS add json upstream/changed")
        f.check([b["host"] for b in tls_json["backends"]] == ["10.0.0.5", "127.0.0.1"],
                "TLS backends sorted", str([b["host"] for b in tls_json["backends"]]))
    ws_remove = f.run([f.go, "--root", tls_root, "xray", "balance", "remove",
                       "--upstream", "ws", "--host", "10.0.0.5"])
    f.check(ws_remove.rc == 0 and not ws_fragment.exists(),
            "TLS ws remove deletes the fragment", ws_remove.text[:200])
    observed["tls"]["nginxTest"] = tls_test.rc
    observed["tls"]["realityRefusal"] = tls_reality.rc

    # ---- S8: Bash baseline, byte for byte ------------------------------
    bash_create = work / "bash-create"
    bash_create.mkdir()
    create_run = run_bash(bash_script(create_fn, "realityServers",
                                      ["10.0.0.2", "8443", "60"]), bash_create, f.env)
    bash_file = bash_create / "10.0.0.2.realityServers"
    bash_bytes = bash_file.read_bytes() if bash_file.is_file() else b""
    f.check(create_run.returncode == 0 and bash_bytes == go_bytes,
            "Bash fm_create_server_file is byte-identical to Go",
            f"bash={sha256_bytes(bash_bytes)} go={sha256_bytes(go_bytes)}")
    bash_delete = work / "bash-delete"
    bash_delete.mkdir()
    write_text(bash_delete / "127.0.0.1.realityServers", loopback_text)
    delete_run = run_bash(bash_script(delete_fn, "realityServers", ["1"],
                                      delete_loopback=True), bash_delete, f.env)
    f.check(delete_run.returncode == 0
            and not (bash_delete / "127.0.0.1.realityServers").exists(),
            "Bash fm_delete_file removes the loopback (no guard)", delete_run.stderr[:200])
    observed["baseline"]["fragmentBytes"] = len(bash_bytes)
    observed["baseline"]["fragmentSha256"] = sha256_bytes(bash_bytes)
    observed["baseline"]["deleteLoopbackRc"] = delete_run.returncode
    compare["fragmentBody"] = {
        "classification": "aligned",
        "goSha256": sha256_bytes(go_bytes),
        "bashSha256": sha256_bytes(bash_bytes),
        "bytes": len(go_bytes),
    }
    compare["fragmentName"] = {
        "classification": "aligned",
        "go": "10.0.0.2.realityServers",
        "bash": "10.0.0.2.realityServers",
    }
    compare["defaultWeight"] = {"classification": "aligned", "value": 50}
    compare["deleteLoopback"] = {
        "classification": "approved-difference",
        "go": "rc=1, refuses the local 127.0.0.1 backend",
        "bash": "rc=0, rm deletes the loopback fragment",
    }
    compare["listOutput"] = {
        "classification": "approved-difference",
        "go": "TSV host/port/weight/file or --json",
        "bash": "file-name table only",
    }
    compare["dupReservedInvalid"] = {
        "classification": "approved-difference",
        "go": "rejects duplicates, reserved ports, invalid hosts and weights",
        "bash": "only character/range input checks; overwrites duplicates",
    }
    compare["reload"] = {
        "classification": "approved-difference",
        "go": "sandbox root skips reload and warns",
        "bash": "always reloads/restarts nginx",
    }
    compare["probe"] = {
        "classification": "new-go-behavior",
        "go": "--probe optional; default warns that nginx passively drops dead backends",
        "bash": "no probe",
    }

    # ---- S9: environment gates -----------------------------------------
    no_meta = work / "gate-no-metadata"
    write_text(no_meta / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    r = f.run([f.go, "--root", no_meta, "xray", "balance", "add", "--upstream", "reality",
               "--host", "10.0.0.9", "--port", "8443"])
    f.check(r.rc == 3 and "缺少 manager metadata" in r.text,
            "root without metadata exits 3", r.text[:200])
    no_anchor = work / "gate-no-anchor"
    write_text(no_anchor / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    write_text(no_anchor / "etc/idleleo/v1/metadata.json",
               json.dumps(metadata("Reality", "raw")) + "\n")
    r = f.run([f.go, "--root", no_anchor, "xray", "balance", "add", "--upstream", "reality",
               "--host", "10.0.0.9", "--port", "8443"])
    f.check(r.rc == 1 and "not a managed Nginx front" in r.text,
            "root without the upstream anchor fails", r.text[:220])
    no_nginx = work / "gate-no-nginx"
    write_text(no_nginx / ".idleleo-phase01-sandbox", "I_ACCEPT_DISPOSABLE_SANDBOX\n")
    (no_nginx / "etc/idleleo/v1").mkdir(parents=True)
    (no_nginx / "etc/idleleo/conf/nginx").mkdir(parents=True)
    write_text(no_nginx / "etc/idleleo/v1/metadata.json",
               json.dumps(metadata("Reality", "raw")) + "\n")
    write_text(no_nginx / "etc/idleleo/conf/nginx/00-xray.conf", anchor)
    write_text(no_nginx / "etc/idleleo/conf/nginx/127.0.0.1.realityServers", loopback_text)
    r = f.run([f.go, "--root", no_nginx, "xray", "balance", "add", "--upstream", "reality",
               "--host", "10.0.0.9", "--port", "8443"])
    f.check(r.rc == 1 and "sbin/nginx" in r.text and not
            (no_nginx / "etc/idleleo/conf/nginx/10.0.0.9.realityServers").exists(),
            "root without nginx removes the new fragment", r.text[:240])

    # ---- S10: read-only tree stability ---------------------------------
    final_before = f.tree_digest(conf_dir)
    f.run([f.go, "--root", root, "xray", "balance", "list", "--upstream", "reality"])
    f.run([f.go, "--root", root, "xray", "balance", "list", "--upstream", "reality", "--json"])
    f.check(f.tree_digest(conf_dir) == final_before,
            "repeated list commands never mutate the tree")

    f.write_json("observed.json", observed)
    f.write_json("baseline-compare.json", compare)


if __name__ == "__main__":
    sys.exit(run_fixture("F09", main))
